  --color-purple-300:    #A7AAF8;
  --color-purple-100:    #CACCFB;
  --color-accent-purple: #9539F2;
  --color-accent-lime:   #BFFF37;

  /* Neutral - dark-first */
  --color-neutral-0:    #0E0E0F;
  --color-neutral-50:   #161618;
  --color-neutral-100:  #242426;
  --color-neutral-200:  #353538;
  --color-neutral-300:  #55555B;
  --color-neutral-500:  #A8A8AD;
  --color-neutral-700:  #D8D8DB;
  --color-neutral-800:  #ECECEE;
  --color-neutral-900:  #F6F6F7;
  --color-neutral-1000: #FFFFFF;

  /* Semantic */
  --color-success-bg: #193108;
  --color-success-fg: #BFFF37;
  --color-warning-bg: #342B0D;
  --color-warning-fg: #F8D85B;
  --color-error-bg:   #3B151D;
  --color-error-fg:   #FF8298;
  --color-info-bg:    #171E58;
  --color-info-fg:    #9DA8FF;

  /* Surface */
  --bg-base:     #0E0E0F;
  --bg-subtle:   #161618;
  --bg-elevated: #242426;
  --bg-overlay:  rgba(0,0,0,0.82);

  /* Text */
  --text-primary:    #FFFFFF;
  --text-secondary:  #CFCFD3;
  --text-tertiary:   #A8A8AD;
  --text-on-primary: #FFFFFF;
  --text-disabled:   rgba(255,255,255,0.30);

  /* Border */
  --border-default: #2C2C2F;
  --border-subtle:  #202023;
  --border-strong:  #47474C;
  --border-focus:   #6F7CFF;
}

